<?php require __DIR__.'/includes/header.php';$cid=currentCompanyId();$rows=db()->query('SELECT r.*,c.name_en company_name,u.name requester FROM update_requests r JOIN companies c ON c.id=r.company_id JOIN users u ON u.id=r.requested_by'.($cid?' WHERE r.company_id='.(int)$cid:'').' ORDER BY r.id DESC')->fetchAll();?><h1><?=t('requests')?></h1><section class="card table-wrap"><table><thead><tr><th>#</th><th><?=t('company')?></th><th>Type</th><th><?=t('status')?></th><th>Date</th><th><?=t('actions')?></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['company_name'])?></td><td><?=e($r['type'])?></td><td><span class="badge <?=$r['status']?>"><?=t($r['status'])?></span></td><td><?=$r['created_at']?></td><td><a class="btn small" href="request-view.php?id=<?=$r['id']?>">👁 <?=t('view')?></a></td></tr><?php endforeach;?></tbody></table></section><?php require __DIR__.'/includes/footer.php';?>
